package com.timborja.tugma.bt.redmibuds

import kotlinx.coroutines.flow.first
import kotlinx.coroutines.test.runTest
import org.junit.jupiter.api.Test
import kotlin.test.assertContentEquals
import kotlin.test.assertEquals
import kotlin.test.assertFailsWith
import kotlin.test.assertNull
import kotlin.test.assertTrue

private fun hex(s: String) = s.chunked(2).map { it.toInt(16).toByte() }.toByteArray()
private fun ByteArray.hex() = joinToString("") { "%02x".format(it) }

class RedmiBudsAuthTest {
    /** Generated by running Gadgetbridge's original Authentication.java on these challenges. */
    @Test
    fun `matches Gadgetbridge's Java implementation`() {
        val vectors = mapOf(
            "00000000000000000000000000000000" to "bca5905bc849392e7bf9fdcdc570ef77",
            "000102030405060708090a0b0c0d0e0f" to "8713913c41434e091cad794a1b5d95c4",
            "ffffffffffffffffffffffffffffffff" to "f26249f9a7bc42731feb945fd9e8d06f",
            "0b30557a9fc4e90e33587da2c7ec1136" to "25bc09c4de0bf7dae5b5ebf689c11509",
        )
        vectors.forEach { (challenge, response) -> assertEquals(response, RedmiBudsAuth.response(hex(challenge)).hex(), challenge) }
    }

    @Test
    fun `doesn't modify the caller's challenge`() {
        val c = hex("000102030405060708090a0b0c0d0e0f")
        RedmiBudsAuth.response(c)
        assertEquals("000102030405060708090a0b0c0d0e0f", c.hex())
        assertFailsWith<IllegalArgumentException> { RedmiBudsAuth.response(ByteArray(15)) }
    }
}

class RedmiMessageTest {
    @Test
    fun `request and response framing`() {
        // Ear detection on: ANC opcode, payload 02 06 00 (from RedmiBudsProtocol.encodeSetEarDetection).
        val req = RedmiMessage(MessageType.PHONE_REQUEST, Opcode.ANC, 5, byteArrayOf(0x02, 0x06, 0x00)).encode()
        assertEquals("fedcbac40800040502060" + "0ef", req.hex())
        val resp = RedmiMessage(MessageType.RESPONSE, Opcode.REPORT_STATUS, 9, ByteArray(0)).encode()
        assertEquals("fedcba040e00020009ef", resp.hex())
    }

    @Test
    fun `decoder reassembles split and back-to-back messages and resyncs`() {
        val a = RedmiMessage(MessageType.EARBUDS_NOTIFY, Opcode.REPORT_STATUS, 1, byteArrayOf(0x04, 0x00, 0x50, 0x4b, 0xb2.toByte())).encode()
        val b = RedmiMessage(MessageType.RESPONSE, Opcode.GET_CONFIG, 2, byteArrayOf(0x03, 0x00, 0x07, 0x05), status = 0).encode()
        val d = RedmiDecoder()
        assertTrue(d.feed(byteArrayOf(0x11, 0x22) + a.copyOfRange(0, 6)).isEmpty())
        val out = d.feed(a.copyOfRange(6, a.size) + b)
        assertEquals(listOf(Opcode.REPORT_STATUS, Opcode.GET_CONFIG), out.map { it.opcode })
        assertEquals(1, out[0].sequence)
        assertContentEquals(byteArrayOf(0x03, 0x00, 0x07, 0x05), out[1].payload)
        val corrupt = a.copyOf().also { it[it.lastIndex] = 0 }
        assertEquals(1, RedmiDecoder().feed(corrupt + b).size)
    }

    @Test
    fun `levels, batteries and versions`() {
        assertEquals(0x86.toByte(), RedmiConfig.encodeLevel(-6))
        assertEquals(-4, RedmiConfig.decodeLevel(0x84.toByte()))
        assertEquals(6, RedmiConfig.decodeLevel(RedmiConfig.encodeLevel(9)))
        assertEquals(BudBattery(50, true), RedmiParsers.battery(0xb2.toByte()))
        assertNull(RedmiParsers.battery(0xff.toByte()))
        assertEquals("1.2.3.4", RedmiParsers.version(0x12, 0x34))
        val eq = RedmiBudsDevice.customEqPayload(listOf(-6, 0, 1, 2, 3, 4, 5, 6, -1, -2))
        assertEquals(37, eq.size)
        assertEquals("2400370501010a", eq.copyOfRange(0, 7).hex())
        assertEquals("003e86", eq.copyOfRange(7, 10).hex(), "62 Hz at -6 dB")
        assertEquals("07e004", eq.copyOfRange(22, 25).hex(), "2016 Hz at +4 dB")
    }

    @Test
    fun `model guessing`() {
        assertEquals("Redmi Buds 6 Pro", RedmiBudsModels.guess("Redmi Buds 6 Pro")?.name)
        assertEquals("Redmi Buds 6", RedmiBudsModels.guess("Redmi Buds 6")?.name)
        assertEquals("Redmi Buds 8 Active", RedmiBudsModels.guess("REDMI Buds 8 Active")?.name)
        assertEquals("Redmi Buds 6 Lite", RedmiBudsModels.guess("Xiaomi Redmi Buds 6 Lite")?.name)
        assertNull(RedmiBudsModels.guess("Galaxy Buds2"))
        assertTrue(RedmiBudsModels.looksLikeRedmiBuds("Redmi Buds 7 Something"))
    }
}

class RedmiBudsDeviceTest {
    @Test
    fun `handshake, initial state, and settings round trip`() = runTest {
        val fake = FakeRedmiBuds()
        val device = RedmiBudsDevice(RedmiBudsModels.byName("Redmi Buds 5 Pro")!!, fake)
        device.start(backgroundScope)

        val s = device.state.first { it.authenticated && it.case != null && it.eqCurve != null && it.toggles.size == 4 }
        assertTrue(fake.authenticated, "fake earbuds verified the phone's challenge answer")
        assertEquals(BudBattery(80, false), s.left)
        assertEquals(BudBattery(50, true), s.case)
        assertEquals("1.2.3.4", s.firmware)
        assertEquals("VID 0x2717, PID 0x506A", s.hardware)
        assertEquals(EqPreset.STANDARD, s.eqPreset)
        assertEquals(true, s.earDetection)
        assertEquals(true, s.toggles[Toggle.DOUBLE_CONNECTION])

        device.setAmbient(AmbientSound.NOISE_CANCELLING)
        device.setAncStrength(AncStrength.DEEP)
        device.setEqPreset(EqPreset.BASS)
        device.setCustomEq(listOf(1, 2, 3, 0, 0, 0, -1, -2, -3, 6))
        device.setToggle(Toggle.AUTO_ANSWER, true)
        device.setEarDetection(false)
        device.findEarbuds(true)
        assertEquals(AmbientSound.NOISE_CANCELLING, fake.ambient)
        assertEquals(AncStrength.DEEP, fake.ancStrength)
        assertEquals(EqPreset.BASS, fake.eqPreset)
        assertEquals(listOf(1, 2, 3, 0, 0, 0, -1, -2, -3, 6), fake.eqCurve)
        assertEquals(true, fake.toggles[Toggle.AUTO_ANSWER])
        assertEquals(false, fake.earDetection)
        assertEquals(1, fake.findRequests)

        // Earbuds push a status change; the phone must acknowledge it.
        fake.left = BudBattery(55, true)
        fake.pushStatus()
        assertEquals(BudBattery(55, true), device.state.first { it.left?.level == 55 }.left)
        device.close()
    }

    @Test
    fun `unavailable modes are refused before anything is sent`() = runTest {
        val device = RedmiBudsDevice(RedmiBudsModels.byName("Redmi Buds 4 Active")!!, FakeRedmiBuds())
        assertFailsWith<IllegalArgumentException> { device.setAmbient(AmbientSound.NOISE_CANCELLING) }
    }
}
